   261  static int
   262  asn1_decode_ec_params(sc_context_t *ctx, void **paramp,
   263          const u8 *buf, size_t buflen, int depth)
   264  {
   265          int r;
   266          struct sc_object_id curve;
   267          struct sc_asn1_entry asn1_ec_params[4];
   268          struct sc_ec_parameters *ecp;
   269
   270          memset(&curve, 0, sizeof(curve));
   271
   272          /* We only want to copy the parms if they are a namedCurve
   273           * or ecParameters  nullParam aka implicityCA is not to be
   274           * used with PKCS#11 2.20 */
   275          sc_copy_asn1_entry(c_asn1_ec_params, asn1_ec_params);
   276          sc_format_asn1_entry(asn1_ec_params + 1, &curve, 0, 0);
   277
   278          /* Some signature algorithms will not have any data */
   279          if (buflen == 0 || buf == NULL)
   280                  return 0;
   281
   282          r = sc_asn1_decode_choice(ctx, asn1_ec_params, buf, buflen, NULL, NULL);
   283          /* r = index in asn1_ec_params */
   284          sc_debug(ctx, SC_LOG_DEBUG_ASN1, "asn1_decode_ec_params r=%d", r);
   285          if (r < 0)
   286                  return r;
   287
   288          ecp = calloc(sizeof(struct sc_ec_parameters), 1);
   289          if (ecp == NULL)
   290                  return SC_ERROR_OUT_OF_MEMORY;
   291
   292          if (r <= 1) {
   293                  ecp->der.value = malloc(buflen);
   294                  if (ecp->der.value == NULL) {
   295                          free(ecp);
   296                          return SC_ERROR_OUT_OF_MEMORY;
   297                  }
   298                  ecp->der.len = buflen;
   299                  memcpy(ecp->der.value, buf, buflen);
   300          }
   301          else    {
   302                  r = 0;
   303          }
   304
   305          ecp->type = r; /* but 0 = ecparams if any, 1=named curve */
   306          *paramp = ecp;
   307          return SC_SUCCESS;
   308  };
