   310  static int
   311  asn1_encode_ec_params(sc_context_t *ctx, void *params,
   312  u8 **buf, size_t *buflen, int depth)
   313  {
   314           struct sc_ec_parameters *ecp = (struct sc_ec_parameters *) params;
   315
   316          /* Only handle named curves. They may be absent too */
   317          sc_debug(ctx, SC_LOG_DEBUG_ASN1, "asn1_encode_ec_params() called");
   318          *buf = NULL;
   319          *buflen = 0;
   320          if (ecp && ecp->type == 1 && ecp->der.value) { /* named curve */
   321                  *buf = malloc(ecp->der.len);
   322                  if (*buf == NULL)
   323                          return SC_ERROR_OUT_OF_MEMORY;
   324
   325                  memcpy(*buf, ecp->der.value, ecp->der.len);
   326                  *buflen = ecp->der.len;
   327          }
   328          else   {
   329                  sc_debug(ctx, SC_LOG_DEBUG_ASN1, "Not named curve");
   330          }
   331
   332          return 0;
   333  }
