   647  static int encode_bit_string(const u8 * inbuf, size_t bits_left, u8 **outbuf,
   648                               size_t *outlen, int invert)
   649  {
   650          const u8 *in = inbuf;
   651          u8 *out;
   652          size_t bytes;
   653          int skipped = 0;
   654
   655          bytes = (bits_left + 7)/8 + 1;
   656          *outbuf = out = malloc(bytes);
   657          if (out == NULL)
   658                  return SC_ERROR_OUT_OF_MEMORY;
   659          *outlen = bytes;
   660          out += 1;
   661          while (bits_left) {
   662                  int i, bits_to_go = 8;
   663
   664                  *out = 0;
   665                  if (bits_left < 8) {
   666                          bits_to_go = bits_left;
   667                          skipped = 8 - bits_left;
   668                  }
   669                  if (invert) {
   670                          for (i = 0; i < bits_to_go; i++)
   671                                  *out |= ((*in >> i) & 1) << (7 - i);
   672                  } else {
   673                          *out = *in;
   674                          if (bits_left < 8)
   675                                  return SC_ERROR_NOT_SUPPORTED; /* FIXME */
   676                  }
   677                  bits_left -= bits_to_go;
   678                  out++, in++;
   679          }
   680          out = *outbuf;
   681          out[0] = skipped;
   682          return 0;
   683  }
