   849           * for the value 2 we can go up to 47. Otherwise the first bit needs to be set
   850           * and we continue reading further */
   851          if ((*p & 0x80) == 0) {
   852                  *octet++ = *p - (a * 40);
   853                  inlen--;
   854          } else {
   855                  large_second_octet = 1;
   856          }
   857
   858          while (inlen) {
   859                  if (!large_second_octet)
