   861                  /* This signalizes empty most significant bits, which means
   862                   * the unsigned integer encoding is not minimal */
   863                  if (*p == 0x80) {
   864                          sc_init_oid(id);
   865                          return SC_ERROR_INVALID_ASN1_OBJECT;
   866                  }
