   873                          if (a > (UINT_MAX>>7)) {
   874                                  sc_init_oid(id);
   875                                  return SC_ERROR_NOT_SUPPORTED;
   876                          }
   877                          p++;
   878                          a <<= 7;
   879                          a |= *p & 0x7F;
   880                          inlen--;
   960          }
